mapper.select:
select `owner_id`,`note_name`,`title`,`category`,`tags`,`source_key`, `is_public`,`content_indexed`,`content`,`preview`,`owner_name`, date_format(`update_time`,'%Y-%m-%d %H:%i') as `update_time` from `note_index` where (`is_public`=1 or `owner_id`=#{currentUserId})
and `owner_id`=#{currentUserId}
and `owner_id`<>#{currentUserId}
and
`title` like concat('%',#{keyword},'%')
`owner_id`=#{currentUserId} and `content_indexed`=1 and `content` like concat('%',#{keyword},'%')
(`title` like concat('%',#{keyword},'%') or (`owner_id`=#{currentUserId} and `content_indexed`=1 and `content` like concat('%',#{keyword},'%')))
order by
(case when `title` like concat('%',#{keyword},'%') then 0 else 1 end) asc,
`update_time` desc, `id` desc limit #{limit}
